import { BUILD_START, DEFAULT_DAYS, DEFAULT_TRAINING_ZONES, type Plan } from './model';
import defaultPlan from './default-plan.json';
import { refineThresholdPlan } from './threshold';
import { unassignPlannedStrength } from './strength';

// Generated by scripts/revise_plan.py and validated by Python and import tests.
export function createDefaultPlan(): Plan {
  const plan = structuredClone(defaultPlan as Plan);
  plan.settings.defaultDays = { ...DEFAULT_DAYS, ...plan.settings.defaultDays };
  plan.settings.trainingZones.hrTargets = { ...DEFAULT_TRAINING_ZONES.hrTargets, ...plan.settings.trainingZones.hrTargets };
  return unassignPlannedStrength(refineThresholdPlan(plan));
}
export const defaultSettings = createDefaultPlan().settings;
export const planWeekNumber = (week: string) => Math.floor((Date.parse(week) - Date.parse(BUILD_START)) / 604800000) + 1;
